fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Pre-allocate enough space for both vectors
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Copy all elements from v1
    result.extend_from_slice(v1);
    // Copy all elements from v2
    result.extend_from_slice(v2);
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // We assume `first` is non-empty as per the problem statement.
    // If you want to enforce it at runtime, you could uncomment the assert below:
    // assert!(!first.is_empty(), "The first vector must be non-empty");

    // Compute the length of the prefix (all except the last element)
    let prefix_len = first.len().saturating_sub(1);
    // Pre-allocate the result vector
    let mut result = Vec::with_capacity(prefix_len + second.len());
    // Copy all but the last element of `first`
    result.extend_from_slice(&first[..prefix_len]);
    // Append all elements of `second`
    result.extend_from_slice(second);
    result
}

